--
-- Table structure for table `goods_receipt_detail`
--

DROP TABLE IF EXISTS `goods_receipt_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `goods_receipt_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `goods_receipt_header` bigint NOT NULL,
  `purchase_order_detail` bigint NOT NULL,
  `qty_received` decimal(12,2) NOT NULL,
  `unit` int NOT NULL,
  `lot_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expired_date` date DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `unit_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtotal` double DEFAULT NULL,
  `status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product` int DEFAULT NULL,
  `deleted` datetime DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `goods_receipt_detail_header_IDX` (`goods_receipt_header`) USING BTREE,
  KEY `goods_receipt_detail_po_detail_IDX` (`purchase_order_detail`) USING BTREE,
  KEY `goods_receipt_detail_lot_number_IDX` (`lot_number`) USING BTREE,
