DROP TABLE IF EXISTS `product_promo_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_promo_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `promo_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_category` int DEFAULT NULL,
  `customer` int DEFAULT NULL,
  `min_qty` double DEFAULT '0',
  `max_qty` double DEFAULT NULL,
  `discount_type` enum('percent','nominal') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'percent',
  `discount_value` double NOT NULL DEFAULT '0',
  `date_start` date DEFAULT NULL,
  `date_end` date DEFAULT NULL,
  `status_aktif` tinyint(1) DEFAULT '1',
  `customer_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `deleted` datetime DEFAULT NULL,
  `unit` int DEFAULT NULL,
  `min_mix` int DEFAULT NULL,
  `kelipatan` int DEFAULT NULL,
  `channel_outlet` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sub_channel_outlet` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_promo_item_customer_IDX` (`customer`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

