--
-- Table structure for table `sales_order_headers`
--

DROP TABLE IF EXISTS `sales_order_headers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_order_headers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `so_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `so_date` date NOT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `payment_term` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_amount` decimal(15,2) DEFAULT '0.00',
  `status` enum('draft','confirmed','cancelled','completed','partial','submited') COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `currency` int DEFAULT NULL,
  `deleted` datetime DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `salesman` int DEFAULT NULL,
  `remarks` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `longitude` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_path` text COLLATE utf8mb4_unicode_ci,
  `signature_path` text COLLATE utf8mb4_unicode_ci,
  `platform` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `check_in_time` datetime DEFAULT NULL,
  `check_out_time` datetime DEFAULT NULL,
  `tax_id` int DEFAULT NULL,
  `tax_amount` double DEFAULT NULL,
  `tax_base` double DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `so_number` (`so_number`),
  KEY `customer_id` (`customer_id`),
  KEY `sales_order_headers_deleted_IDX` (`deleted`) USING BTREE,
  KEY `sales_order_headers_salesman_IDX` (`salesman`) USING BTREE,
  CONSTRAINT `sales_order_headers_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

